import os
import zipfile
import io
from flask import Flask, request, jsonify

app = Flask(__name__)


def extract_text_from_zip(zip_data):
    """Extract and concatenate contents of all text files from a zip archive."""
    text_parts = []
    try:
        with zipfile.ZipFile(io.BytesIO(zip_data), 'r') as zf:
            for member in zf.namelist():
                if member.endswith('.txt'):
                    try:
                        content = zf.read(member)
                        # Decode as UTF-8, replacing errors if necessary
                        text = content.decode('utf-8', errors='replace')
                        text_parts.append(text)
                    except Exception:
                        # Skip files that can't be read/decoded
                        continue
    except zipfile.BadZipFile:
        raise ValueError("Invalid zip file")
    except Exception:
        raise ValueError("Error processing zip file")

    return ''.join(text_parts)


@app.route('/convert', methods=['POST'])
def convert():
    # Check if file part is present
    if 'file' not in request.files:
        return jsonify({'error': 'No file part'}), 400

    file = request.files['file']

    # Check if filename is empty
    if file.filename == '':
        return jsonify({'error': 'No selected file'}), 400

    # Read the file data
    zip_data = file.read()

    if not zip_data:
        return jsonify({'error': 'Empty file'}), 400

    try:
        # Extract text from zip
        text_content = extract_text_from_zip(zip_data)

        if not text_content.strip():
            # Return empty string if no text files found or empty content
            return '', 200

        return text_content, 200

    except ValueError as e:
        return jsonify({'error': str(e)}), 400
    except Exception as e:
        return jsonify({'error': 'Internal server error'}), 500


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
